import 'dart:convert';
import 'dart:math';

import 'package:flutter/foundation.dart';
import 'package:pointycastle/export.dart';

class Encodes {
  static const String cPASSWORDCRYPTKEY =
      r'*&^K^%X威dVd56T6$M$J$#sw冠H#q1@Q@$A$&*fdNd';
  static const String cDCMFILECRYPTKEY = r'%$%###&*@~!~!?/.@#$$%^&*';

  static String encryptText(String plaintext, String passphrase) {
    final plaintextBytes = utf8.encode(plaintext);

    return encrypt(plaintextBytes, passphrase);
  }

  static String encrypt(Uint8List plaintextBytes, String passphrase) {
    final random = Random();
    final passphraseBytes = utf8.encode(passphrase);
    final salt = Uint8List(8);
    for (var i = 0; i < 8; i++) {
      salt[i] = random.nextInt(256);
    }
    final sha1 = Digest('SHA-1');
    sha1.update(passphraseBytes, 0, passphraseBytes.length);
    sha1.update(salt, 0, salt.length);
    final keyCheck = sha1.process(Uint8List(0)).sublist(0, 8);
    final message = Uint8List.fromList([...keyCheck, ...plaintextBytes]);
    const blockSize = 8;
    final remainder = message.length % blockSize;
    final paddingLen = remainder == 0 ? blockSize : blockSize - remainder;
    final paddedMessage = Uint8List(message.length + paddingLen);
    paddedMessage.setRange(0, message.length, message);
    for (var i = message.length; i < paddedMessage.length; i++) {
      paddedMessage[i] = paddingLen;
    }
    final keyIv = mash([...passphraseBytes, ...salt], 24, 200);
    final key = keyIv.sublist(0, 16);
    final iv = keyIv.sublist(16, 24);
    final cipher = CBCBlockCipher(DESedeEngine())
      ..init(true, ParametersWithIV(KeyParameter(expandKey(key)), iv));
    final ciphertext = processBlocks(cipher, paddedMessage);
    final macKey = mash(passphraseBytes, 16, 1);
    final hmac = HMac(SHA1Digest(), 64)..init(KeyParameter(macKey));
    hmac.update(plaintextBytes, 0, plaintextBytes.length);
    final mac = hmac.process(Uint8List(0));
    final result = Uint8List(salt.length + ciphertext.length + mac.length);
    result.setRange(0, salt.length, salt);
    result.setRange(salt.length, salt.length + ciphertext.length, ciphertext);
    result.setRange(salt.length + ciphertext.length, result.length, mac);
    return bytesToHex(result);
  }

  static String? dcmDecrypt(hexCiphertext, passphrase) {
    /*final hexCiphertext =
        '';
    final passphrase = '%\$%###&*@~!~!?/.@#\$\$%^&*';*/
    final raw = hexToBytes(hexCiphertext);
    final passphraseBytes = utf8.encode(passphrase);
    final salt = raw.sublist(0, 8);
    final ciphertext = raw.sublist(8, raw.length - 20);
    final macReceived = raw.sublist(raw.length - 20);

    // 派生 key/iv
    final keyIv = mash([...passphraseBytes, ...salt], 24, 200);
    final key = keyIv.sublist(0, 16);
    final iv = keyIv.sublist(16, 24);

    // 3DES 解密
    final cipher = CBCBlockCipher(DESedeEngine())
      ..init(false, ParametersWithIV(KeyParameter(expandKey(key)), iv));
    final paddedPlain = processBlocks(cipher, ciphertext);

    // 校验 keyCheck
    final sha1 = Digest('SHA-1');
    sha1.update(passphraseBytes, 0, passphraseBytes.length);
    sha1.update(salt, 0, salt.length);
    final keyCheck = sha1.process(Uint8List(0)).sublist(0, 8);
    if (!listEquals(paddedPlain.sublist(0, 8), keyCheck)) {
      debugPrint('密钥校验失败');
      return null;
    }
    final message = paddedPlain.sublist(8);

    // 校验 MAC
    final macKey = mash(passphraseBytes, 16, 1);
    final hmac = HMac(SHA1Digest(), 64)..init(KeyParameter(macKey));
    hmac.update(message, 0, message.length);
    final macComputed = Uint8List(20)..setAll(0, hmac.process(Uint8List(0)));
    if (!listEquals(macComputed, macReceived)) {
      debugPrint('MAC 校验失败');
      return null;
    }

    return utf8.decode(message);
  }

  // 工具函数
  static Uint8List hexToBytes(String hex) {
    hex = hex.replaceAll(' ', '');
    final result = Uint8List(hex.length ~/ 2);
    for (var i = 0; i < result.length; i++) {
      result[i] = int.parse(hex.substring(i * 2, i * 2 + 2), radix: 16);
    }
    return result;
  }

  static Uint8List mash(List<int> input, int outLen, int iterations) {
    final sha1 = SHA1Digest();
    final bufSize = ((outLen + 19) ~/ 20) * 20;
    var outBuf = Uint8List(bufSize);
    var b = Uint8List(2);

    for (var i = 0; i < outLen; i += 20) {
      b[0] = (i >> 8) & 0xff;
      b[1] = i & 0xff;
      sha1.reset();
      sha1.update(b, 0, 2);
      sha1.update(Uint8List.fromList(input), 0, input.length);
      final d = sha1.process(Uint8List(0));
      outBuf.setRange(i, i + 20, d);
    }
    for (var iter = 1; iter < iterations; iter++) {
      final buf = Uint8List.fromList(outBuf);
      for (var i = 0; i < bufSize; i += 20) {
        b[0] = (i >> 8) & 0xff;
        b[1] = i & 0xff;
        sha1.reset();
        sha1.update(b, 0, 2);
        sha1.update(buf, 0, buf.length);
        final d = sha1.process(Uint8List(0));
        outBuf.setRange(i, i + 20, d);
      }
    }
    return Uint8List.fromList(outBuf.sublist(0, outLen));
  }

  static Uint8List expandKey(Uint8List key16) {
    // 2-key 3DES: K1,K2,K1
    if (key16.length == 16) {
      return Uint8List.fromList([...key16, ...key16.sublist(0, 8)]);
    }
    return key16;
  }

  static Uint8List processBlocks(BlockCipher cipher, Uint8List input) {
    final out = Uint8List(input.length);
    for (var offset = 0; offset < input.length; offset += cipher.blockSize) {
      cipher.processBlock(input, offset, out, offset);
    }
    return out;
  }

  static bool listEquals(List<int> a, List<int> b) {
    if (a.length != b.length) return false;
    for (var i = 0; i < a.length; i++) {
      if (a[i] != b[i]) return false;
    }
    return true;
  }

  static String bytesToHex(Uint8List bytes) {
    return bytes.map((b) => b.toRadixString(16).padLeft(2, '0')).join('');
  }

  static Uint8List unpad(Uint8List data, int blockSize) {
    if (data.isEmpty) return data;
    final paddingLen = data.last;
    if (paddingLen > blockSize || paddingLen == 0) return data;
    for (var i = data.length - paddingLen; i < data.length; i++) {
      if (data[i] != paddingLen) return data;
    }
    return data.sublist(0, data.length - paddingLen);
  }
}
